/* @lc app=leetcode id=2131 lang=kotlin */
class Solution { fun longestPalindrome(words: Array<String>): Int = words.groupBy { it }.mapValues { it.value.size }.let { counts -> counts.keys.filter { it[0] == it[1] }.any { counts[it]!! % 2 == 1 }.let { hasMid -> counts.keys.sumOf { w -> if (w[0] == w[1]) (counts[w]!! / 2) * 4 else if (w < w.reversed()) minOf(counts[w]!!, counts[w.reversed()] ?: 0) * 4 else 0 } + if (hasMid) 2 else 0 } } }